contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public payable {
        // Read the current MinSum before the call.
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        // The deciding call: may succeed or revert.
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // Read MinSum after the call.
        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(reverted ? minSumAfter == minSumBefore : minSumAfter == _val);
    }
}

